import React, { useEffect, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { VictoryPie, VictoryContainer } from 'victory';
import { getVulnsCountByStatus, getVulnsCountBySeverity } from 'Screens/Contextualization/Dashboard/actions/Actions';
import { buildVulnsCountParams } from 'services/api/dashboard/queryParams';
import { CLOSED_FILTERS, CONFIRMED_FLAG_FILTERS } from 'store/Filters/constants';
import { isFilteringBy } from 'store/Filters/selectors';
import SpinnerComponent from 'Common/Components/SpinnerContainer';
import formatNumber from 'Common/Functions/FormatNumber';
import colors from 'Styles/colors';
import { formatRemediationWarning } from '../common/formatWidgetMessages';
import {
  Wrapper,
  Empty,
  ContentWrapper,
  PieWrapper,
  GrayRingSvg,
  Footer,
  FooterItem,
  FooterLabel,
  CardValue,
  CenterLabel,
  CenterValue,
  CenterText,
  FooterInfo,
  FooterSubtitle,
  Header,
  HeaderItem,
  CenterPercentage,
  ExcludeIcon
} from './styled';
import { useIntl } from 'react-intl';
import { selectCurrentWorkspace } from 'store/Faraday/selectors';
import { selectPreferences } from 'store/Preferences/selectors';
import TitleWrapper from '../components/TitleWrapper';

const Remediation = () => {
  const dispatch = useDispatch();
  const workspaceSelected = useSelector(selectCurrentWorkspace);
  const { theme } = useSelector(selectPreferences);

  const { confirmed } = CONFIRMED_FLAG_FILTERS;
  const { notClosed: closedFilter } = CLOSED_FILTERS;
  const isFilteringByConfirm = useSelector((state) => isFilteringBy(state, 'vulns', confirmed));
  const isFilteringByClosed = useSelector((state) => isFilteringBy(state, 'vulns', closedFilter));

  const intl = useIntl();
  const translations = useMemo(
    () => ({
      remediation: intl.formatMessage({ id: 'dashboard.widgets.remediation' }),
      remediated: intl.formatMessage({ id: 'dashboard.widgets.remediated' }),
      info: intl.formatMessage({ id: 'dashboard.widgets.remediation.info' }),
      empty: intl.formatMessage({ id: 'dashboard.widgets.emptyVulnerability' }),
      stillOpen: intl.formatMessage({ id: 'dashboard.widgets.still_open' }),
      highRisk: intl.formatMessage({ id: 'dashboard.widgets.high_risk' }),
      critical: intl.formatMessage({
        id: 'dashboard.widgets.remediation.critical'
      }),
      highAwaitingTriage: intl.formatMessage({
        id: 'dashboard.widgets.high_awaiting_triage'
      }),
      closed: intl.formatMessage({ id: 'dashboard.widgets.closed' }),
      open: intl.formatMessage({ id: 'dashboard.widgets.open' }),
      total: intl.formatMessage({ id: 'dashboard.widgets.total' })
    }),
    [intl]
  );

  const isFetching = useSelector(
    (state) => state.dashboard?.loadingState?.vulnCountByStatus ?? false
  );

  const vulnCountByStatus = useSelector(
    (state) => state.dashboard?.vulnCountByStatus ?? {}
  );

  const vulnCountBySeverity = useSelector(
    (state) => state.dashboard?.vulnCountBySeverity ?? {}
  );

  const vulnCountReloadToken = useSelector(
    (state) => state.dashboard?.vulnCountReloadToken ?? 0
  );

  const open = vulnCountByStatus.open ?? 0;
  const reopen = vulnCountByStatus.reopen ?? 0;
  const closed = vulnCountByStatus.closed ?? 0;
  const riskAccepted = vulnCountByStatus.riskAccepted ?? 0;

  const total = open + reopen + closed + riskAccepted;
  const remediated = closed + riskAccepted;

  const remediationPercent =
    total > 0 ? Math.round((remediated / total) * 100) : 0;
  const openTotal = open + reopen;

  const critical = vulnCountBySeverity.critical ?? 0;
  const high = vulnCountBySeverity.high ?? 0;

  const headerMessage = formatRemediationWarning({
    openTotal,
    critical,
    high,
    translations
  });

  const data = [
    { name: 'Closed', value: remediated },
    { name: 'Open', value: openTotal }
  ];

  // Same filterParams shape BySeverity builds — the confirmed/not-closed
  // toggle now lives in WorkspaceHeader and affects every widget that reads
  // it, this one included, so both the pie (status) and the header warning
  // (severity) below reflect it too.
  const filterParams = useMemo(
    () =>
      buildVulnsCountParams({
        confirmed: isFilteringByConfirm,
        notClosed: isFilteringByClosed
      }),
    [isFilteringByConfirm, isFilteringByClosed]
  );

  useEffect(() => {
    dispatch(getVulnsCountByStatus(filterParams));
  }, [dispatch, workspaceSelected, filterParams, vulnCountReloadToken]);

  // Fetches its own severity counts instead of depending on the BySeverity
  // widget having mounted and dispatched them — same filterParams as
  // BySeverity, so the request dedupes into one when both are on screen.
  useEffect(() => {
    dispatch(getVulnsCountBySeverity(filterParams));
  }, [dispatch, workspaceSelected, filterParams, vulnCountReloadToken]);

  const graphBarColor = theme === 'dark' ? colors.dark9 : colors.blue8;

  if (isFetching) return <SpinnerComponent height="250px" />;

  return (
    <Wrapper>
      <TitleWrapper title={ translations.remediation } info={ translations.info } icon={ <ExcludeIcon /> } />
      {total === 0
        ? (
        <Empty>{translations.empty}</Empty>
          )
        : (
        <>
          <Header>
            <HeaderItem>{headerMessage}</HeaderItem>
          </Header>
          <ContentWrapper>
            <PieWrapper>
              <GrayRingSvg viewBox="0 0 200 180">
                <circle
                  cx="100"
                  cy="90"
                  r="59"
                  fill="none"
                  stroke={ graphBarColor }
                  strokeWidth="18"
                />
              </GrayRingSvg>
              <VictoryPie
                data={ data }
                x="name"
                y="value"
                style={ {
                  data: {
                    fill: ({ datum }) =>
                      datum.name === 'Closed' ? colors.apple : graphBarColor,
                    stroke: graphBarColor
                  }
                } }
                height={ 180 }
                width={ 200 }
                radius={ 68 }
                innerRadius={ 50 }
                cornerRadius={ ({ datum }) => (datum.name === 'Closed' ? 10 : 0) }
                labels={ () => '' }
                containerComponent={ <VictoryContainer responsive={ false } /> }
              />
              <CenterLabel>
                <CenterValue>
                  {remediationPercent}
                  <CenterPercentage>%</CenterPercentage>
                </CenterValue>
                <CenterText status="closed">
                  {translations.remediated}
                </CenterText>
              </CenterLabel>
            </PieWrapper>
            <Footer>
              <FooterItem status="open">
                <FooterInfo>
                  <FooterLabel>{translations.open}</FooterLabel>
                  <FooterSubtitle>{translations.total}</FooterSubtitle>
                </FooterInfo>

                <CardValue>{formatNumber(openTotal)}</CardValue>
              </FooterItem>

              <FooterItem status="closed">
                <FooterInfo>
                  <FooterLabel>{translations.closed}</FooterLabel>
                  <FooterSubtitle>{translations.total}</FooterSubtitle>
                </FooterInfo>

                <CardValue>{formatNumber(remediated)}</CardValue>
              </FooterItem>
            </Footer>
          </ContentWrapper>
        </>
          )}
    </Wrapper>
  );
};

export default Remediation;
